#include <chrono>
#include <iostream>

int main() {
    // Simple arithmetic:
    std::chrono::seconds s = std::chrono::hours(1) + 2 * std::chrono::minutes(10) +
        std::chrono::seconds(70) / 10;
    std::cout << "1 hour + 2*10 min + 70/10 sec = " << s << " (seconds)\n";

    using namespace std::chrono_literals;

    // Difference between dividing a duration by a number
    // and dividing a duration by another duration:
    std::cout << "Dividing that by 2 minutes gives " << s / 2min << '\n'
              << "Dividing that by 2 gives " << (s / 2).count() << " seconds\n";

    // The remainder operator is useful in determining where
    // in a time frame is this particular duration, e.g. to
    // break it down into hours, minutes, and seconds:
    std::cout << s
              << " (seconds) = " << std::chrono::duration_cast<std::chrono::hours>(s)
              << " (hour) + "
              << std::chrono::duration_cast<std::chrono::minutes>(s % 1h)
              << " (minutes) + "
              << std::chrono::duration_cast<std::chrono::seconds>(s % 1min)
              << " (seconds)\n";

    constexpr auto sun_earth_distance{150'000'000ULL};           // km
    constexpr auto speed_of_light{300000ULL};                    // km/sec
    std::chrono::seconds t(sun_earth_distance / speed_of_light); // sec
    std::cout << "A photon flies from the Sun to the Earth in " << t / 1min
              << " minutes " << t % 1min << " (seconds)\n";
}
